import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../core/app_controller.dart';
import '../widgets/common.dart';

class WifiScreen extends StatefulWidget{const WifiScreen({super.key});@override State<WifiScreen> createState()=>_WifiScreenState();}
class _WifiScreenState extends State<WifiScreen>{bool loading=false;Future<void>buy(Map<String,dynamic> n,Map<String,dynamic>d)async{final app=context.read<AppController>();final phone=TextEditingController(text:app.user?.phone??'');setState(()=>loading=true);try{final id=int.tryParse('${n['id']}')??0, did=int.tryParse('${d['id']}')??0, price=num.tryParse('${d['sale_price']??d['price']??0}')??0;final r=await app.api.wifiPurchase(networkId:id,denominationId:did,phone:phone.text,price:price.toDouble());await app.refreshAll();if(mounted)showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تم شراء الكرت'),content:Text('PIN: ${r['pin']??r['card_pin']??'-'}\nSerial: ${r['serial']??r['serial_number']??'-'}'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('تم'))]));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString())));}finally{phone.dispose();if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext context){final app=context.watch<AppController>();return Stack(children:[Scaffold(appBar:AppBar(title:const Text('شبكات وكروت الوايفاي')),body:RefreshIndicator(onRefresh:app.refreshAll,child:ListView(padding:const EdgeInsets.all(12),children:[SectionHeader(title:'الشبكات المتاحة',color:Colors.teal.shade700),const SizedBox(height:8),if(app.wifi.isEmpty)const PageCard(child:Text('لا توجد شبكات متاحة من الخادم.',textAlign:TextAlign.center)) else ...app.wifi.map((n)=>Padding(padding:const EdgeInsets.only(bottom:8),child:PageCard(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('${n['name']??'شبكة'}',style:const TextStyle(fontWeight:FontWeight.w900,fontSize:14)),Text('${n['location']??n['description']??''}',style:const TextStyle(color:Colors.black54,fontSize:10)),const SizedBox(height:7),...((n['denominations'] is List)?(n['denominations'] as List).map((d)=>ListTile(contentPadding:EdgeInsets.zero,dense:true,title:Text('${d['name']??'فئة'}',style:const TextStyle(fontSize:11,fontWeight:FontWeight.w800)),subtitle:Text('${d['available_cards']??''} متاح',style:const TextStyle(fontSize:9)),trailing:FilledButton(onPressed:loading?null:()=>buy(Map<String,dynamic>.from(n),Map<String,dynamic>.from(d)),child:Text('${d['sale_price']??d['price']??''}')))).toList():[]) ])))),const SizedBox(height:10),SectionHeader(title:'الكروت المشتراة',color:AppColors.blue),const SizedBox(height:8),if(app.wifiCards.isEmpty)const PageCard(child:Text('لا توجد كروت مشتراة.',textAlign:TextAlign.center)) else ...app.wifiCards.map((c)=>Padding(padding:const EdgeInsets.only(bottom:6),child:PageCard(child:Row(children:[const Icon(Icons.confirmation_number_outlined,color:AppColors.blue),const SizedBox(width:8),Expanded(child:Text('PIN: ${c['pin']??c['card_pin']??'-'}\nSerial: ${c['serial']??c['serial_number']??'-'}',textAlign:TextAlign.right,style:const TextStyle(fontSize:11,fontWeight:FontWeight.w700))),]))))]))),if(loading)const BusyOverlay(visible:true)]);}}
